use std::{fs,time::Instant};use wasmc_json_component::{Lib,wasmtime};use wasmc_json_component::exports::wasmc::json::document::JsonField;use wasmtime::{Engine,Store};use wasmtime::component::{Component,Linker};
fn main(){let started=Instant::now();let e=Engine::default();let c=Component::new(&e,fs::read("publication/wasmc-json/component.wasm").unwrap()).unwrap();let mut s=Store::new(&e,());let lib=Lib::instantiate(&mut s,&c,&Linker::new(&e)).unwrap();let d=lib.wasmc_json_document();let payload="x".repeat(17*1024*1024+1);let input=format!("\"{}\"",payload);let values=vec![input];let array=d.call_array_from_values_or(&mut s,&values,"failed").unwrap();assert_eq!(array.len(),payload.len()+4);assert_eq!(&array[0..2],"[\"");assert_eq!(&array[array.len()-2..],"\"]");assert_eq!(&array[2..array.len()-2],payload);let fields=vec![JsonField{name:"items".into(),value_json:array}];let obj=d.call_object_from_fields_or(&mut s,&fields,"failed").unwrap();assert_eq!(obj.len(),payload.len()+14);assert_eq!(&obj[..11],"{\"items\":[\"");assert_eq!(&obj[obj.len()-3..],"\"]}");assert_eq!(&obj[11..obj.len()-3],payload);assert_eq!(d.call_array_from_values_or(&mut s,&["bad".into()],"[]").unwrap(),"[]");assert_eq!(d.call_array_from_values_or(&mut s,&["true".into()],"[]").unwrap(),"[true]");println!("{{\"accepted\":true,\"engine\":\"wasmtime-component\",\"payload_bytes\":{},\"output_bytes\":{},\"same_instance_recovery\":true,\"elapsed_ms\":{}}}",payload.len(),obj.len(),started.elapsed().as_millis());}
